mutation CreateNodeWithAttributes($content: String!, $tableId: ID!, $attributes: [NodeAttributeInput!]) {
  createNode(
    input: {
      content: $content
      tableId: $tableId
      attributes: $attributes
    }
  ) {
    success
    node {
      id
      content
      table {
        id
        identifier
      }
      attributes {
        id
        value
        attribute {
          identifier
          name
          attributeType {
            name
            dataType
          }
        }
        createdAt
      }
      attributeCount
      createdAt
      updatedAt
    }
    errors {
      message
      code
      field
    }
  }
}
